--
-- Name: powersync_ensure_ingredient_synced(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.powersync_ensure_ingredient_synced(ing_id bigint) RETURNS void
    LANGUAGE sql
    AS $$
        INSERT INTO nutrition_synced_ingredient
            SELECT * FROM nutrition_ingredient WHERE id = ing_id
            ON CONFLICT (id) DO NOTHING;
    $$;


--
-- Name: powersync_propagate_ingredient(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.powersync_propagate_ingredient() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
            IF EXISTS (SELECT 1 FROM nutrition_synced_ingredient WHERE id = NEW.id) THEN
                DELETE FROM nutrition_synced_ingredient WHERE id = NEW.id;
                INSERT INTO nutrition_synced_ingredient
                    SELECT * FROM nutrition_ingredient WHERE id = NEW.id;
            END IF;
            RETURN NEW;
        END $$;


--
-- Name: powersync_sync_ingredient_from_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.powersync_sync_ingredient_from_item() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
            PERFORM powersync_ensure_ingredient_synced(NEW.ingredient_id);
            RETURN NEW;
        END $$;


